/* ============================================================
   RankForge Kenya — site.css
   Design system per blueprint: violet/lilac SEO agency marketing site
   4 pages, one shared stylesheet, mobile-first responsive
   ============================================================ */

/* ----------------------------- Tokens ----------------------------- */
:root {
  /* Color tokens */
  --ground-primary: #FFFFFF;
  --ground-lilac: #F6F4FD;
  --ground-deep: #0D0D12;
  --accent: #6D28D9;
  --accent-strong: #5B21B6;
  --accent-soft: #EDE9FD;
  --ink-heading: #1A1333;
  --ink-body: #565071;
  --ink-muted: #8B84A3;
  --hairline: #E4E0F2;
  --on-dark: #FFFFFF;
  --on-dark-muted: rgba(255, 255, 255, 0.72);

  /* Layout tokens */
  --container: 1200px;
  --gutter: 24px;
  --section-pad: 96px;
  --split-gap: 64px;

  /* Shape tokens */
  --radius-card: 18px;
  --radius-photo: 24px;
  --radius-input: 10px;
  --radius-tile: 16px;
  --radius-pill: 999px;

  /* Shadow tokens */
  --shadow-rest: 0 6px 20px rgba(45, 27, 88, 0.06);
  --shadow-hover: 0 14px 32px rgba(45, 27, 88, 0.10);
  --shadow-header: 0 2px 12px rgba(45, 27, 88, 0.08);

  /* Typography tokens */
  --font-body: 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-display: 'Poppins', 'Inter', system-ui, sans-serif;

  /* Misc */
  --header-h: 72px;
  --nav-overlay-speed: 300ms;
}

/* ----------------------------- Reset ------------------------------ */
*,
*::before,
*::after { box-sizing: border-box; }

html {
  scroll-behavior: smooth;
  scroll-padding-top: var(--header-h);
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: var(--font-body);
  font-size: 15px;
  line-height: 1.6;
  color: var(--ink-body);
  background: var(--ground-primary);
}

body.nav-open { overflow: hidden; }

img { max-width: 100%; display: block; }

a { color: var(--accent); }

h1, h2, h3, h4 {
  font-family: var(--font-display);
  color: var(--ink-heading);
  font-weight: 700;
  margin: 0 0 16px;
  line-height: 1.12;
}

p { margin: 0 0 16px; max-width: 62ch; }

ul, ol { margin: 0; padding: 0; list-style: none; }

button { font-family: inherit; cursor: pointer; }

/* Skip link */
.skip-link {
  position: absolute;
  left: 16px;
  top: -60px;
  z-index: 200;
  background: var(--accent);
  color: #fff;
  padding: 10px 18px;
  border-radius: 0 0 10px 10px;
  font-weight: 600;
  font-size: 14px;
  text-decoration: none;
  transition: top 200ms ease;
}
.skip-link:focus { top: 0; }

/* Focus visibility */
a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
summary:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

/* --------------------------- Layout core --------------------------- */
.container {
  width: 100%;
  max-width: var(--container);
  margin-inline: auto;
  padding-inline: var(--gutter);
}

main { display: block; }

.section { padding-block: var(--section-pad); }

.section--lilac { background: var(--ground-lilac); }
.section--white { background: var(--ground-primary); }
.section--deep { background: var(--ground-deep); }

.hairline-top { border-top: 1px solid var(--hairline); }

/* Section split layouts */
.split {
  display: grid;
  grid-template-columns: 1fr;
  gap: 40px;
  align-items: center;
}

@media (min-width: 900px) {
  .split { grid-template-columns: 1fr 1fr; gap: var(--split-gap); }
  .split--55-45 { grid-template-columns: 55fr 45fr; }
  .split--45-55 { grid-template-columns: 45fr 55fr; }
  .split--40-60 { grid-template-columns: 40fr 60fr; }
  .split--60-40 { grid-template-columns: 60fr 40fr; }
}

/* --------------------------- Type scale --------------------------- */
.h1 {
  font-size: clamp(44px, 6vw, 84px);
  font-weight: 800;
  line-height: 1.05;
  max-width: 15ch;
}

.h2 {
  font-size: clamp(30px, 3.4vw, 44px);
  font-weight: 700;
  line-height: 1.12;
  max-width: 22ch;
}

.h2--light { color: #fff; }

.h3 {
  font-size: clamp(22px, 2vw, 28px);
  font-weight: 700;
}

/* Accent span inside headings (violet wrapped line) */
.h1 .accent-span,
.h2 .accent-span { color: var(--accent); }

/* Chips / kickers */
.chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--accent);
  color: #fff;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.04em;
  line-height: 1;
  padding: 8px 16px;
  border-radius: var(--radius-pill);
  max-width: 20ch;
}

.chip--soft {
  background: var(--accent-soft);
  color: var(--accent);
}

.chip--glass {
  background: rgba(255, 255, 255, 0.2);
  color: #fff;
  border: 1px solid rgba(255, 255, 255, 0.3);
}

/* ----------------------------- Buttons ---------------------------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  background: var(--accent);
  color: #fff;
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 600;
  line-height: 1.2;
  padding: 14px 28px;
  border: none;
  border-radius: var(--radius-pill);
  text-decoration: none;
  transition: background 300ms ease, transform 300ms ease, box-shadow 300ms ease;
}

.btn:hover { background: var(--accent-strong); transform: translateY(-1px); box-shadow: 0 8px 20px rgba(109, 40, 217, 0.25); }
.btn:active { transform: translateY(0); }

.btn__arrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.18);
  font-size: 11px;
}

/* Ghost pill (card-level secondary action) */
.btn--ghost {
  background: #fff;
  color: var(--accent);
  border: 1px solid #D8CCF7;
  font-size: 13px;
  padding: 9px 18px;
}

.btn--ghost:hover { background: var(--ground-lilac); transform: none; box-shadow: none; }

.btn--light {
  background: #fff;
  color: var(--accent);
}

.btn--light:hover { background: var(--accent-soft); }

/* ------------------------------ Header ---------------------------- */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: transparent;
  border-bottom: 1px solid transparent;
  transition: background 250ms ease, border-color 250ms ease, box-shadow 250ms ease;
}

.site-header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  height: var(--header-h);
}

.site-header__logo {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 20px;
  text-decoration: none;
  color: #fff;
  transition: color 250ms ease;
}

.site-header__logo .logo-mark { color: var(--accent); }

.site-header__nav { display: none; }

.site-header__nav a {
  color: rgba(255, 255, 255, 0.92);
  text-decoration: none;
  font-size: 15px;
  font-weight: 500;
  transition: color 200ms ease;
}

.site-header__nav a:hover,
.site-header__nav a[aria-current="page"] { color: var(--accent); }

/* Scrolled state (JS toggles .is-scrolled) */
.site-header.is-scrolled {
  background: #fff;
  border-bottom-color: var(--hairline);
  box-shadow: var(--shadow-header);
}

.site-header.is-scrolled .site-header__logo,
.site-header.is-scrolled .site-header__nav a { color: #3A3153; }

.site-header.is-scrolled .site-header__nav a:hover,
.site-header.is-scrolled .site-header__nav a[aria-current="page"] { color: var(--accent); }

/* Inner pages: header always solid */
.page--inner .site-header {
  background: #fff;
  border-bottom-color: var(--hairline);
  box-shadow: var(--shadow-header);
}

.page--inner .site-header .site-header__logo,
.page--inner .site-header .site-header__nav a { color: #3A3153; }

.page--inner .site-header .site-header__nav a:hover,
.page--inner .site-header .site-header__nav a[aria-current="page"] { color: var(--accent); }

/* Hamburger */
.nav-toggle {
  display: inline-flex;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 40px;
  height: 40px;
  padding: 8px;
  background: transparent;
  border: none;
}

.nav-toggle span {
  display: block;
  height: 2px;
  width: 100%;
  background: currentColor;
  border-radius: 2px;
  color: #fff;
  transition: transform 250ms ease, opacity 250ms ease, color 250ms ease;
}

.site-header.is-scrolled .nav-toggle span,
.page--inner .nav-toggle span { color: var(--ink-heading); }

/* Mobile nav overlay */
.mobile-nav {
  position: fixed;
  inset: 0;
  z-index: 150;
  background: #fff;
  transform: translateX(100%);
  transition: transform var(--nav-overlay-speed) ease;
  display: flex;
  flex-direction: column;
  padding: 24px;
}

.mobile-nav.is-open { transform: translateX(0); }

.mobile-nav__close {
  align-self: flex-end;
  width: 40px;
  height: 40px;
  border: none;
  background: var(--accent-soft);
  border-radius: 10px;
  color: var(--accent);
  font-size: 18px;
}

.mobile-nav__links {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 32px;
}

.mobile-nav__links a {
  font-size: 18px;
  font-weight: 600;
  color: var(--ink-heading);
  text-decoration: none;
  padding: 12px 4px;
}

.mobile-nav__links a[aria-current="page"] { color: var(--accent); }

.mobile-nav .btn { margin-top: auto; }

@media (min-width: 1024px) {
  .site-header__nav {
    display: flex;
    align-items: center;
    gap: 28px;
  }
  .nav-toggle { display: none; }
  .mobile-nav { display: none; }
  .site-header__cta { display: inline-flex; }
}

.site-header__cta { display: none; }

/* ------------------------------ Hero ------------------------------ */
/* Full-bleed photo hero with dark overlay + rounded panel */
.hero {
  position: relative;
  display: flex;
  align-items: center;
  min-height: 92svh;
  padding-top: var(--header-h);
  overflow: hidden;
  background: var(--ground-deep);
  isolation: isolate;
}

.hero--inner {
  min-height: 60svh;
}

.hero__media,
.hero__media img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: -2;
}

.hero__media { z-index: -2; }

.hero__scrim {
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    linear-gradient(180deg, rgba(23, 16, 43, 0.55) 0%, rgba(23, 16, 43, 0.72) 55%, rgba(23, 16, 43, 0.88) 100%),
    linear-gradient(100deg, rgba(109, 40, 217, 0.55) 0%, rgba(23, 16, 43, 0.35) 60%);
}

.hero__panel {
  position: relative;
  background: rgba(42, 33, 80, 0.85);
  border-radius: 16px;
  padding: 36px;
  max-width: 520px;
  color: #fff;
  box-shadow: 0 18px 44px rgba(13, 10, 30, 0.35);
}

/* Rank 1 finding: inset the panel ~56px from the left container edge
   on desktop so the photo breathes left of the panel (centered-left mass). */
@media (min-width: 900px) {
  .hero__panel { margin-left: 56px; }
}

.hero__panel .chip { margin-bottom: 20px; }

.hero__panel .h1 { color: #fff; margin-bottom: 18px; }

.hero__panel p {
  color: rgba(255, 255, 255, 0.85);
  font-size: 14px;
  line-height: 1.6;
}

.hero__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 16px;
  margin-top: 24px;
}

/* Availability / status badge with pulse dot */
.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.9);
}

.status-badge .pulse-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #2FBF71;
  animation: pulse 1.6s ease-in-out infinite;
}

@keyframes pulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(47, 191, 113, 0.5); }
  50% { box-shadow: 0 0 0 6px rgba(47, 191, 113, 0); }
}

/* Inner-page hero (60vh with panel) */
.hero--inner .hero__panel { max-width: 480px; }
.hero--inner .h1 { font-size: clamp(34px, 4vw, 56px); line-height: 1.08; }

/* --------------------------- About band --------------------------- */
.about-band__media {
  position: relative;
  border-radius: var(--radius-photo);
  overflow: hidden;
  background: var(--accent-soft);
}

.about-band__media img {
  width: 100%;
  height: 100%;
  min-height: 340px;
  object-fit: cover;
}

.about-band__media::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(109, 40, 217, 0.28), rgba(237, 233, 253, 0.05));
  mix-blend-mode: multiply;
  pointer-events: none;
}

/* Dotted grid motif */
.dotted-grid {
  position: relative;
}

.dotted-grid::before {
  content: "";
  position: absolute;
  top: -24px;
  left: -24px;
  width: 160px;
  height: 160px;
  background-image: radial-gradient(rgba(109, 40, 217, 0.35) 1.5px, transparent 1.5px);
  background-size: 16px 16px;
  border-radius: 8px;
  z-index: 0;
  pointer-events: none;
}

.kicker-line {
  border-left: 3px solid var(--accent);
  padding-left: 14px;
  font-size: 14px;
  font-weight: 600;
  color: var(--ink-heading);
  margin-bottom: 16px;
}

/* Checklist with violet circular checks */
.checklist li {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  font-size: 15px;
  font-weight: 600;
  color: #3A3153;
  margin-bottom: 12px;
}

.checklist .check-dot {
  flex: 0 0 auto;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--accent);
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  margin-top: 1px;
}

/* ---------------------------- Marquee band ------------------------ */
.logo-marquee {
  background: var(--accent);
  height: 56px;
  max-height: 64px;
  overflow: hidden;
  display: flex;
  align-items: center;
}

.logo-marquee__track {
  display: flex;
  align-items: center;
  gap: 56px;
  white-space: nowrap;
  animation: marquee 28s linear infinite;
  padding-left: 28px;
}

.logo-marquee:hover .logo-marquee__track { animation-play-state: paused; }

.logo-marquee__track span {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 15px;
  color: rgba(255, 255, 255, 0.62);
  filter: grayscale(1);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

@keyframes marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}

/* ------------------------ Icon chip cards ------------------------- */
.icon-tile {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  border-radius: var(--radius-tile);
  background: var(--accent-soft);
  color: var(--accent);
  flex: 0 0 auto;
}

.icon-tile--lg {
  width: 64px;
  height: 64px;
}

.icon-tile svg { width: 28px; height: 28px; }

.icon-row {
  display: flex;
  gap: 18px;
  align-items: flex-start;
  margin-bottom: 24px;
}

.icon-row h3 {
  font-size: 17px;
  font-weight: 700;
  margin-bottom: 4px;
}

.icon-row p {
  font-size: 14px;
  margin: 0;
  max-width: 48ch;
}

/* Card grid (services) */
.card-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 640px) {
  .card-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 1024px) {
  .card-grid--4 { grid-template-columns: repeat(4, 1fr); }
  .card-grid--4 + .card-grid--4 { margin-top: 24px; }
}

.card {
  background: #FCFBFF;
  border: 1px solid var(--hairline);
  border-radius: 20px;
  padding: 28px;
  box-shadow: var(--shadow-rest);
  transition: box-shadow 200ms ease-out, border-color 200ms ease-out, transform 200ms ease-out;
}

.card:hover {
  box-shadow: var(--shadow-hover);
  border-color: #D8CCF7;
  transform: translateY(-3px);
}

.card h3 {
  font-size: 17px;
  font-weight: 700;
  line-height: 1.25;
  margin: 18px 0 8px;
}

.card p {
  font-size: 14px;
  margin-bottom: 18px;
}

/* Full-width horizontal split card (flagship offering) */
.card--split {
  display: flex;
  flex-direction: column;
  gap: 24px;
  margin-top: 24px;
  padding: 32px;
}

/* Rank 2 finding: rebuild as horizontal 3-column anatomy on desktop
   (icon tile | copy block | right-aligned CTA column). */
@media (min-width: 900px) {
  .card--split {
    flex-direction: row;
    align-items: center;
    gap: 32px;
  }
  .card--split .card--split__icon { flex: 0 0 96px; }
  .card--split .card--split__body { flex: 1; }
  .card--split .card--split__actions {
    flex: 0 0 auto;
    flex-direction: column;
    align-items: flex-end;
  }
}

@media (max-width: 899px) {
  .card--split__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 0;
  }
}

.card--split__body h3 { margin-top: 0; }

.card--split__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 8px;
}

/* -------------------------- Floating stats ------------------------ */
.stat-media {
  position: relative;
  border-radius: var(--radius-photo);
  overflow: visible;
}

.stat-media img {
  width: 100%;
  min-height: 440px;
  object-fit: cover;
  border-radius: var(--radius-photo);
}

.stat-card {
  position: absolute;
  background: #fff;
  border-radius: 16px;
  padding: 20px 22px;
  box-shadow: 0 12px 30px rgba(45, 27, 88, 0.16);
  min-width: 200px;
  max-width: 230px;
}

.stat-card--top-right { top: 24px; right: -12px; }
.stat-card--bottom-left { bottom: 24px; left: -12px; }

.stat-card .icon-tile {
  width: 44px;
  height: 44px;
  margin-bottom: 12px;
}

.stat-card .stat-label {
  font-size: 12px;
  color: var(--ink-muted);
  font-weight: 500;
  margin: 0 0 4px;
}

.stat-card .stat-value {
  font-family: var(--font-display);
  font-size: clamp(26px, 2.4vw, 34px);
  font-weight: 800;
  line-height: 1;
  color: var(--ink-heading);
  margin: 0;
}

/* ------------------------------ FAQ ------------------------------- */
.faq-illustration {
  background: var(--accent-soft);
  border-radius: 16px;
  padding: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  min-height: 220px;
}

.faq-illustration svg { width: 180px; height: auto; color: var(--accent); }

.faq-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.faq-item { border-radius: 12px; overflow: hidden; }

/* Collapsed violet bars — signature trait */
.faq-item__bar {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  background: var(--accent);
  color: #fff;
  border: none;
  padding: 18px 22px;
  border-radius: 12px;
  font-family: var(--font-body);
  font-size: 15px;
  font-weight: 600;
  text-align: left;
  transition: background 400ms ease;
}

.faq-item__bar:hover,
.faq-item.is-open .faq-item__bar { background: #7C3AED; }

.faq-item__plus {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  border: 1.5px solid rgba(255, 255, 255, 0.85);
  color: #fff;
  font-size: 16px;
  line-height: 1;
  transition: transform 400ms ease;
  flex: 0 0 auto;
}

.faq-item.is-open .faq-item__plus { transform: rotate(45deg); }

.faq-item__answer {
  background: #fff;
  border: 1px solid var(--hairline);
  border-top: none;
  border-radius: 0 0 14px 14px;
  padding: 20px 22px;
  font-size: 14px;
  color: var(--ink-body);
  overflow: hidden;
}

.faq-item.is-open .faq-item__answer { border-radius: 0 0 14px 14px; }

.faq-item.is-open .faq-item__bar { border-radius: 12px 12px 0 0; }

/* Expanded standalone card style */
.faq-item--expanded .faq-item__bar {
  background: #fff;
  color: var(--ink-heading);
  border: 1px solid var(--hairline);
  border-bottom: none;
  border-radius: 14px 14px 0 0;
  box-shadow: var(--shadow-rest);
}

.faq-item--expanded .faq-item__bar:hover { background: #fff; }

.faq-item--expanded .faq-item__plus {
  background: var(--accent);
  border-color: var(--accent);
}

.faq-item--expanded .faq-item__answer {
  box-shadow: var(--shadow-rest);
}

/* -------------------------- Testimonials -------------------------- */
.testimonial-band {
  position: relative;
  padding-block: var(--section-pad);
  overflow: hidden;
  isolation: isolate;
  background: var(--ground-deep);
}

.testimonial-band__media,
.testimonial-band__media img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: -2;
}

.testimonial-band__media { z-index: -2; }

.testimonial-band__scrim {
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    linear-gradient(180deg, rgba(109, 40, 217, 0.55), rgba(23, 16, 43, 0.7)),
    rgba(109, 40, 217, 0.35);
  mix-blend-mode: normal;
}

.quote-cards {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.quote-card {
  position: relative;
  background: #fff;
  border-radius: 18px;
  padding: 28px;
  box-shadow: var(--shadow-rest);
  overflow: hidden;
  transition: box-shadow 200ms ease-out, transform 200ms ease-out;
}

.quote-card:hover { box-shadow: var(--shadow-hover); transform: translateY(-3px); }

.quote-card__portrait {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  border: 3px solid var(--accent-soft);
  background: var(--accent);
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 22px;
  margin-bottom: 14px;
}

.quote-card__stars {
  color: #F59E0B;
  font-size: 14px;
  letter-spacing: 2px;
  margin-bottom: 10px;
}

.quote-card blockquote {
  margin: 0 0 16px;
  font-size: 14px;
  color: var(--ink-body);
}

.quote-card cite {
  display: block;
  font-style: normal;
}

.quote-card .quote-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--ink-heading);
}

.quote-card .quote-role {
  font-size: 12px;
  color: var(--ink-muted);
}

/* Rank 3 finding: translucent quote glyph bottom-right of each card. */
.quote-card__glyph {
  position: absolute;
  right: 16px;
  bottom: 4px;
  font-family: Georgia, serif;
  font-size: 96px;
  line-height: 1;
  color: rgba(255, 255, 255, 0.35);
  pointer-events: none;
}

@media (min-width: 900px) {
  .quote-cards {
    flex-direction: row;
    max-width: 640px;
  }
  .quote-cards .quote-card { flex: 1; }
}

/* Rank 3 finding: carousel dots beneath the card pair. */
.quote-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 32px;
}

.quote-dots__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.4);
}

.quote-dots__dot.is-active { background: #fff; }

/* ---------------------------- Newsletter -------------------------- */
.newsletter {
  border-top: 1px solid var(--hairline);
  border-bottom: 1px solid var(--hairline);
}

.newsletter__title {
  color: var(--accent);
  font-size: clamp(22px, 2vw, 28px);
  font-weight: 700;
}

.newsletter-form .field-row {
  display: grid;
  grid-template-columns: 1fr;
  gap: 14px;
}

@media (min-width: 640px) {
  .newsletter-form .field-row { grid-template-columns: 1fr 1fr; }
}

.newsletter-form .field { margin-bottom: 14px; }

.newsletter-form .field--full { grid-column: 1 / -1; }

.newsletter-form input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--accent);
}

/* ------------------------------ Forms ----------------------------- */
.field { margin-bottom: 18px; }

.field label {
  display: block;
  font-size: 14px;
  font-weight: 600;
  color: var(--ink-heading);
  margin-bottom: 6px;
}

.field input,
.field select,
.field textarea {
  width: 100%;
  min-height: 46px;
  padding: 12px 14px;
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--ink-heading);
  background: #fff;
  border: 1px solid var(--hairline);
  border-radius: var(--radius-input);
  transition: border-color 200ms ease, box-shadow 200ms ease;
}

.field textarea { min-height: 120px; resize: vertical; }

.field input:focus,
.field select:focus,
.field textarea:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(109, 40, 217, 0.12);
}

.field input[aria-invalid="true"],
.field textarea[aria-invalid="true"],
.field select[aria-invalid="true"] {
  border-color: #D92D20;
}

.field__hint {
  font-size: 12px;
  color: var(--ink-muted);
  margin-top: 4px;
}

.form-error {
  color: #D92D20;
  font-size: 13px;
  margin: 0 0 14px;
}

.form-note {
  font-size: 13px;
  color: var(--ink-muted);
}

/* Contact form card */
.contact-card {
  background: #fff;
  border: 1px solid var(--hairline);
  border-radius: 20px;
  padding: 36px;
  box-shadow: var(--shadow-rest);
}

/* ------------------------- Contact CTA + footer -------------------- */
.cta-deep {
  position: relative;
  background: var(--ground-deep);
  color: var(--on-dark);
  text-align: center;
  overflow: hidden;
  padding-top: var(--section-pad);
}

.cta-deep .h2--light { margin-inline: auto; }

.cta-deep__sub {
  color: var(--on-dark-muted);
  max-width: 52ch;
  margin-inline: auto;
}

.cta-deep__actions {
  display: flex;
  justify-content: center;
  margin-top: 28px;
}

.availability-strip {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 28px;
  margin-top: 40px;
}

.availability-strip li {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.85);
}

.availability-strip svg {
  width: 16px;
  height: 16px;
  color: var(--accent);
}

/* Violet diagonal ribbon rising beneath the CTA into footer */
.ribbon {
  position: relative;
  height: 220px;
  background: var(--ground-deep);
  overflow: hidden;
}

.ribbon::before {
  content: "";
  position: absolute;
  left: -10%;
  right: -10%;
  bottom: -160px;
  height: 320px;
  background: var(--accent);
  transform: rotate(-4deg);
  border-radius: 40px 40px 0 0;
}

.ribbon::after {
  content: "";
  position: absolute;
  left: -10%;
  right: -10%;
  bottom: -220px;
  height: 320px;
  background: linear-gradient(100deg, var(--accent-strong), var(--accent));
  transform: rotate(3deg);
  border-radius: 40px 40px 0 0;
  opacity: 0.85;
}

/* Floating white contact strip card over the seam */
.contact-strip {
  position: relative;
  z-index: 2;
  margin-top: -140px;
  margin-bottom: 0;
}

.contact-strip__card {
  background: #fff;
  border-radius: 20px;
  padding: 28px 32px;
  box-shadow: 0 20px 50px rgba(13, 10, 30, 0.35);
  display: flex;
  flex-direction: column;
  gap: 18px;
  align-items: flex-start;
}

@media (min-width: 900px) {
  .contact-strip__card {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.contact-strip__logo {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 20px;
  color: var(--ink-heading);
}

.contact-strip__logo .logo-mark { color: var(--accent); }

.contact-strip__location {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  color: var(--ink-body);
}

.contact-strip__location svg { width: 16px; height: 16px; color: var(--accent); }

.contact-strip__email {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 600;
  color: var(--ink-heading);
  text-decoration: none;
}

.contact-strip__email svg { width: 16px; height: 16px; color: var(--accent); }
.contact-strip__email:hover { color: var(--accent); }

/* Footer */
.site-footer {
  background: var(--ground-deep);
  color: var(--on-dark);
  padding-top: 72px;
  margin-top: -60px;
  position: relative;
}

.site-footer::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 120px;
  background: linear-gradient(180deg, var(--accent) 0%, rgba(109, 40, 217, 0) 100%);
  opacity: 0.35;
  transform: skewY(-2deg);
  transform-origin: top left;
  pointer-events: none;
}

.footer-grid {
  position: relative;
  display: grid;
  grid-template-columns: 1fr;
  gap: 40px;
  padding-bottom: 56px;
}

@media (min-width: 640px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (min-width: 1024px) {
  .footer-grid { grid-template-columns: 1.4fr 1fr 1fr 1.2fr; }
}

.footer-brand p {
  color: var(--on-dark-muted);
  font-size: 14px;
  max-width: 34ch;
}

.footer-brand .footer-logo {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 20px;
  color: #fff;
  text-decoration: none;
  display: inline-block;
  margin-bottom: 14px;
}

.footer-brand .footer-logo .logo-mark { color: #A78BFA; }

.social-row {
  display: flex;
  gap: 10px;
  margin-top: 18px;
}

.social-row a {
  width: 40px;
  height: 40px;
  border-radius: 8px;
  background: #1C1725;
  color: var(--accent-soft);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
  transition: background 200ms ease, color 200ms ease;
}

.social-row a:hover { background: var(--accent); color: #fff; }

.social-row svg { width: 18px; height: 18px; }

.footer-heading {
  font-size: 14px;
  font-weight: 700;
  color: #fff;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  margin-bottom: 18px;
}

.footer-links li { margin-bottom: 10px; }

.footer-links a {
  color: var(--on-dark-muted);
  font-size: 13.5px;
  text-decoration: none;
  transition: color 200ms ease;
}

.footer-links a:hover { color: #fff; }

.footer-subscribe p {
  color: var(--on-dark-muted);
  font-size: 13.5px;
}

.footer-subscribe__row {
  display: flex;
  gap: 10px;
}

.footer-subscribe__row input {
  flex: 1;
  min-width: 0;
  min-height: 46px;
  padding: 12px 14px;
  font-size: 14px;
  color: #fff;
  background: #1C1725;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 10px;
}

.footer-subscribe__row input::placeholder { color: rgba(255, 255, 255, 0.45); }

.footer-subscribe__row input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(109, 40, 217, 0.25);
}

.footer-subscribe__row .btn {
  padding: 12px 20px;
  white-space: nowrap;
}

.footer-bottom {
  position: relative;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  padding-block: 22px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: flex-start;
}

@media (min-width: 640px) {
  .footer-bottom {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.footer-bottom__legal {
  display: flex;
  gap: 20px;
}

.footer-bottom a {
  color: var(--on-dark-muted);
  font-size: 13px;
  text-decoration: none;
}

.footer-bottom a:hover { color: #fff; }

.footer-bottom__copy {
  color: var(--on-dark-muted);
  font-size: 13px;
}

/* ----------------------- Section reveals (JS-enhanced) ------------- */
/* Resting state fully visible; site.js animates FROM offset to this. */
.js .reveal {
  opacity: 1;
  transform: none;
}

.js .reveal.is-revealing {
  animation: reveal-in 700ms ease-out both;
}

@keyframes reveal-in {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ------------------------ Responsive tweaks ------------------------ */
@media (max-width: 1023px) {
  :root { --section-pad: 72px; }
  .hero { min-height: 80svh; }
  .hero--inner { min-height: 50svh; }
}

@media (max-width: 639px) {
  :root { --section-pad: 64px; --gutter: 16px; }
  .hero { min-height: 70svh; }
  .hero--inner { min-height: 44svh; }
  .hero__panel { padding: 24px; }
  .h1 { font-size: clamp(34px, 10vw, 44px); }
  .hero--inner .h1 { font-size: clamp(28px, 8vw, 36px); }
  .stat-card--top-right { top: 12px; right: 8px; }
  .stat-card--bottom-left { bottom: 12px; left: 8px; }
  .stat-card { min-width: 0; max-width: 200px; padding: 16px; }
  .stat-media img { min-height: 340px; }
  .faq-illustration { display: none; }
  .contact-card { padding: 24px; }
  .card--split { padding: 24px; }
  .card--split__icon .icon-tile { width: 72px; height: 72px; }
  .testimonial-band__media img { background-attachment: scroll; }
}

/* ------------------------ Reduced motion --------------------------- */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .logo-marquee__track { animation: none; }

  .js .reveal.is-revealing { animation: none; }

  .btn:hover,
  .card:hover,
  .quote-card:hover { transform: none; }

  .faq-item__plus { transition: none; }

  .status-badge .pulse-dot { animation: none; }
}

