/* ============================================================
   RankForge Kenya — site.js
   Dependency-free progressive enhancement: header state, mobile nav,
   FAQ accordion, form validation UX, scroll reveals (JS-only).
   Content is fully visible without JavaScript; JS only enhances.
   ============================================================ */
(function () {
  'use strict';

  function ready(fn) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', fn);
    } else {
      fn();
    }
  }

  ready(function () {
    var reduceMotion = window.matchMedia &&
      window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    /* ---------- Mark JS availability (reveals become animated) ---------- */
    document.documentElement.classList.add('js');

    /* ---------------------- Sticky header state ---------------------- */
    var header = document.querySelector('.site-header');
    if (header) {
      var onScroll = function () {
        if (window.scrollY > 60) {
          header.classList.add('is-scrolled');
        } else {
          header.classList.remove('is-scrolled');
        }
      };
      window.addEventListener('scroll', onScroll, { passive: true });
      onScroll();
    }

    /* ------------------------ Mobile navigation ---------------------- */
    var navToggle = document.querySelector('.nav-toggle');
    var mobileNav = document.querySelector('.mobile-nav');
    var navClose = document.querySelector('.mobile-nav__close');

    function openNav() {
      if (!mobileNav) return;
      mobileNav.classList.add('is-open');
      mobileNav.setAttribute('aria-hidden', 'false');
      document.body.classList.add('nav-open');
      if (navToggle) navToggle.setAttribute('aria-expanded', 'true');
      var firstLink = mobileNav.querySelector('a, button');
      if (firstLink) firstLink.focus();
    }

    function closeNav() {
      if (!mobileNav) return;
      mobileNav.classList.remove('is-open');
      mobileNav.setAttribute('aria-hidden', 'true');
      document.body.classList.remove('nav-open');
      if (navToggle) {
        navToggle.setAttribute('aria-expanded', 'false');
        navToggle.focus();
      }
    }

    if (navToggle && mobileNav) {
      navToggle.setAttribute('aria-expanded', 'false');
      mobileNav.setAttribute('aria-hidden', 'true');
      navToggle.addEventListener('click', function () {
        if (mobileNav.classList.contains('is-open')) {
          closeNav();
        } else {
          openNav();
        }
      });
    }

    if (navClose) navClose.addEventListener('click', closeNav);

    if (mobileNav) {
      mobileNav.addEventListener('click', function (e) {
        if (e.target === mobileNav) closeNav();
      });
      var navLinks = mobileNav.querySelectorAll('a');
      for (var i = 0; i < navLinks.length; i++) {
        navLinks[i].addEventListener('click', closeNav);
      }
    }

    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && mobileNav && mobileNav.classList.contains('is-open')) {
        closeNav();
      }
    });

    /* -------------------------- FAQ accordion ------------------------ */
    var faqItems = document.querySelectorAll('.faq-item');
    Array.prototype.forEach.call(faqItems, function (item) {
      var bar = item.querySelector('.faq-item__bar');
      var answer = item.querySelector('.faq-item__answer');
      if (!bar || !answer) return;

      var open = item.classList.contains('is-open');
      bar.setAttribute('aria-expanded', open ? 'true' : 'false');
      answer.hidden = !open;

      bar.addEventListener('click', function () {
        var nowOpen = !item.classList.contains('is-open');
        item.classList.toggle('is-open', nowOpen);
        bar.setAttribute('aria-expanded', nowOpen ? 'true' : 'false');
        answer.hidden = !nowOpen;
      });
    });

    /* -------------------- Basic form validation UX ------------------- */
    var forms = document.querySelectorAll('form');
    Array.prototype.forEach.call(forms, function (form) {
      form.setAttribute('novalidate', 'novalidate');

      form.addEventListener('submit', function (e) {
        var invalid = null;
        var fields = form.querySelectorAll('input[required], select[required], textarea[required]');

        Array.prototype.forEach.call(fields, function (field) {
          var ok = field.value && field.value.trim().length > 0;
          if (field.type === 'email' && ok) {
            ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(field.value.trim());
          }
          if (field.type === 'checkbox' && !field.checked) ok = false;
          field.setAttribute('aria-invalid', ok ? 'false' : 'true');
          if (!ok && !invalid) invalid = field;
        });

        var honeypot = form.querySelector('input[name="_gotcha"]');
        if (honeypot && honeypot.value) {
          e.preventDefault();
          return;
        }

        if (invalid) {
          e.preventDefault();
          invalid.focus();
          return;
        }

        /* Success UX for forms without a navigation target is handled
           by the browser submitting to the form action endpoint. */
      });
    });

    /* --------------------- Scroll reveals (enhancement) -------------- */
    var revealEls = document.querySelectorAll('.reveal');
    if (!reduceMotion && 'IntersectionObserver' in window && revealEls.length > 0) {
      var observer = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-revealing');
            observer.unobserve(entry.target);
          }
        });
      }, { threshold: 0.2 });

      Array.prototype.forEach.call(revealEls, function (el) {
        observer.observe(el);
      });
    }
  });
})();
